static void nav_refresh(void)
{
    char buf[32];
    double ridden = 1.6;
    double pct;

    if (UN.rem == NULL) {
        return;
    }
    if (R.active) {
        ridden += R.dist_km;
    }
    if (ridden > 10.0) {
        ridden = 10.0;
    }
    pct = ridden / 10.0;

    snprintf(buf, sizeof(buf), "%.1f", 10.0 - ridden);
    lv_label_set_text(UN.rem, buf);
    snprintf(buf, sizeof(buf), "已骑 %.1f km", ridden);
    lv_label_set_text(UN.ridden, buf);
    snprintf(buf, sizeof(buf), "已完成 %d%%", (int)lround(pct * 100.0));
    lv_label_set_text(UN.frac, buf);
    lv_obj_set_width(UN.prog_fill, pct * 192.0 < 2.0 ? 2 : (int)(pct * 192.0));
    lv_obj_set_x(UN.prog_knob, 24 + (int)(pct * 192.0) - 1);

    {
        int sec = s_min * 60 + (int)((10.0 - ridden) / 20.0 * 3600.0);
        int eta = (sec / 60) % 1440;

        snprintf(buf, sizeof(buf), "%d:%02d", eta / 60, eta % 60);
        lv_label_set_text(UN.eta, buf);
    }
    if (R.active) {
        int m = 480 - (int)(R.elapsed_s * 10) % 480;

        if (m <= 0) m = 480;
        snprintf(buf, sizeof(buf), "%d m", (m / 10) * 10);
        lv_label_set_text(UN.turn, buf);
    }
}

static void nav_map(lv_obj_t *scr)
{
