#define SCENE_COUNT (sizeof(s_scenes) / sizeof(s_scenes[0]))

const sim_scene_t *sim_scene_find(const char *name)
{
    if (!name) {
        return NULL;
    }
    for (size_t i = 0; i < SCENE_COUNT; i++) {
        if (strcmp(s_scenes[i].name, name) == 0) {
            return &s_scenes[i];
        }
    }
    return NULL;
}

void sim_scene_list(void)
{
    puts("可用场景:");
    for (size_t i = 0; i < SCENE_COUNT; i++) {
        printf("  %-8s %s\n", s_scenes[i].name, s_scenes[i].desc);
    }
}

