static void sensor_tick(void)
{
    if (s_sens_search < 0) {
        return;
    }
    s_sens_ticks++;
    s_sens_blink = ((s_sens_ticks / 1) % 2) == 0;
    if (s_sens_ticks >= 3) {
        const int i = s_sens_search;

        s_sens_search = -1;
        s_sens_on[i] = true;
        s_sens_bars[i] = 4;
        if (i == 2) {
            snprintf(s_sens_dev[2], sizeof(s_sens_dev[2]), "Magene S3+");
        }
        toast("已连接");
    }
    if (s_screen == SCR_SENSOR) {
        sens_values();
    }
}

static void go_back(void)
{
    switch (s_screen) {
        case SCR_DISPLAY:
        case SCR_SENSOR:
        case SCR_ABOUT:
            s_busy = true;
            s_tr_next = SCR_SETTINGS;
            s_tr_post = POST_NONE;
            {
                lv_obj_t *bar = (s_screen == SCR_DISPLAY) ? UP.titlebar
                                : (s_screen == SCR_SENSOR) ? UX.titlebar
                                                           : UA.titlebar;

                if (bar != NULL) {
                    lv_obj_set_width(bar, 20);
                    {
                        lv_anim_t a;

                        lv_anim_init(&a);
                        lv_anim_set_var(&a, bar);
                        lv_anim_set_values(&a, 20, 0);
                        lv_anim_set_duration(&a, 100);
                        lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                        lv_anim_set_exec_cb(&a,
                                            (lv_anim_exec_xcb_t)lv_obj_set_width);
                        lv_anim_start(&a);
                    }
                }
            }
            {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, &s_tr_p);
                lv_anim_set_values(&a, 0, 1000);
                lv_anim_set_duration(&a, 100);
                lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                lv_anim_set_exec_cb(&a, tr_exec);
                lv_anim_set_ready_cb(&a, tr_done);
                s_tr_cy0 = 146;
                s_tr_cy1 = 146;
                s_tr_d0 = 160;
                s_tr_d1 = 160;
                s_tr_anim = lv_anim_start(&a);
            }
            break;

        case SCR_RIDE: {
            /* ANIMATION #4：hero 60ms 退出 → 硬切 → 环展开 120ms。 */
            s_busy = true;
            if (UR.hero_box != NULL) {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, UR.hero_box);
                lv_anim_set_values(&a, 255, 0);
                lv_anim_set_duration(&a, 60);
                lv_anim_set_exec_cb(&a, hero_opa_exec);
                lv_anim_start(&a);
            }
            s_tr_next = SCR_DIAL;
            s_tr_post = POST_DIAL_FROM_RIDE;
            {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, &s_tr_p);
                lv_anim_set_values(&a, 0, 1000);
                lv_anim_set_duration(&a, 60);
                lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                lv_anim_set_exec_cb(&a, tr_exec);
                lv_anim_set_ready_cb(&a, tr_done);
                s_tr_cy0 = 146;
                s_tr_cy1 = 146;
                s_tr_d0 = 160;
                s_tr_d1 = 160;
                s_tr_anim = lv_anim_start(&a);
            }
            break;
        }

        case SCR_NAV:
        case SCR_RECORD:
            s_screen = SCR_DIAL;
            rebuild();
            dial_in(120, 120, 160);
            break;

        case SCR_SETTINGS:
            s_screen = SCR_DIAL;
            rebuild();
            dial_in(120, 120, 160);
            break;

        default:
            break;
    }
}

/* ── rebuild / scene ───────────────────────────────────────────── */

static void rebuild(void)
{
    lv_obj_t *old = s_scr;

    /* 先停掉所有以「即将被删的对象」为变量的动画，避免 var 悬空。 */
    lv_anim_delete(&s_rot_p, NULL);
    lv_anim_delete(&s_tr_p, NULL);
    lv_anim_delete(&s_in_p, NULL);
    lv_anim_delete(&s_post_p, NULL);
    s_rot_anim = NULL;
    s_tr_anim = NULL;
    s_post_anim = NULL;
    if (UC.bar != NULL) lv_anim_delete(UC.bar, NULL);
    if (US.bar != NULL) lv_anim_delete(US.bar, NULL);
    if (UP.bar != NULL) lv_anim_delete(UP.bar, NULL);
    if (UX.bar != NULL) lv_anim_delete(UX.bar, NULL);
    if (US.titlebar != NULL) lv_anim_delete(US.titlebar, NULL);
    if (UP.titlebar != NULL) lv_anim_delete(UP.titlebar, NULL);
    if (UX.titlebar != NULL) lv_anim_delete(UX.titlebar, NULL);
    if (UA.titlebar != NULL) lv_anim_delete(UA.titlebar, NULL);
    if (UR.hero_box != NULL) lv_anim_delete(UR.hero_box, NULL);
    if (LP.arc != NULL) lv_anim_delete(LP.arc, NULL);
    if (LP.bar != NULL) lv_anim_delete(LP.bar, NULL);
    lp_ui_clear();
    LP.active = false;

    nav_stop();
    memset(&UD, 0, sizeof(UD));
    memset(&UR, 0, sizeof(UR));
    memset(&UN, 0, sizeof(UN));
    memset(&UC, 0, sizeof(UC));
    memset(&US, 0, sizeof(US));
    memset(&UP, 0, sizeof(UP));
    memset(&UX, 0, sizeof(UX));
    memset(&UA, 0, sizeof(UA));
    s_hint = NULL;
    pts_reset();
    lv_obj_clean(old);

    switch (s_screen) {
        case SCR_RIDE: ride_build(); break;
        case SCR_NAV: nav_build(); break;
        case SCR_RECORD: rec_build(); break;
        case SCR_SETTINGS: set_build(); break;
        case SCR_DISPLAY: disp_build(); break;
        case SCR_SENSOR: sens_build(); break;
        case SCR_ABOUT: about_build(); break;
        case SCR_ICONS: icons_build(false); break;
        case SCR_ICONS_DEMO: icons_build(true); break;
        case SCR_ICON_OPT: iconopt_build(); break;
        default: dial_build(); break;
    }
    if (s_toast_until != 0 && lv_tick_get() < s_toast_until) {
        hint_set(s_toast_msg);
    }
