        s_min = (s_min + 1) % (24 * 60);
        if (s_screen == SCR_DIAL) {
            dial_status_refresh();
        }
    }
    if (s_clock_tick % 120 == 0 && s_batt > 5) {
        s_batt--;
        if (s_screen == SCR_DIAL) {
            dial_status_refresh();
        }
    }
    if (s_sens_search >= 0) {
        sensor_tick();
    }
    if (R.active) {
        R.elapsed_s++;
        ride_step();
        if (s_screen == SCR_RIDE) {
            ride_refresh();
        } else if (s_screen == SCR_NAV) {
            nav_refresh();
#ifdef SIM_WITH_UI
            if (s_nav_view != NULL) {
                vmap_view_set_center(s_nav_view,
                                     s_nav_lon + R.dist_km * 0.00004,
                                     s_nav_lat);
            }
#endif
        } else if (s_screen == SCR_DIAL) {
            if (!LP.active && s_rot_anim == NULL) {
                dial_content(s_mode);
            }
            dial_status_refresh();
        }
    }
}

