    if (sim_png_write(path, fb, w, h)) {
        printf("helm-tour: shot %s\n", path);
        fflush(stdout);
    } else {
        fprintf(stderr, "helm-tour: failed %s\n", path);
    }
}

static void tour_tick(void)
{
    if (!s_tour_on) {
        return;
    }
    s_tour_frame++;
    while (s_tour_idx < (int)(sizeof(TOUR) / sizeof(TOUR[0])) &&
           TOUR[s_tour_idx].f <= (int)s_tour_frame) {
        const tour_ev_t *e = &TOUR[s_tour_idx];

        s_tour_idx++;
        if (e->kind == 's') {
            tour_shot(e->a);
        } else {
            sim_display_inject_key(e->a, e->b != 0);
        }
    }
    if (s_tour_idx >= (int)(sizeof(TOUR) / sizeof(TOUR[0]))) {
        s_tour_on = false;
    }
}

