#define SIM_FONT_CACHE 12

static struct {
    int px;
    bool italic;
    lv_font_t *font;
} s_cache[SIM_FONT_CACHE];
static int s_cache_n;

static const char *cjk_font_path(void)
{
    const char *env = getenv("SIM_CJK_FONT");

    if (env && env[0]) {
        return env;
    }
    /* 用**码表固件里那份** TTF（MiSans-Medium 子集），字形与板端一致。
     * 设备路径是 /mnt/fat/fonts/MiSans-Medium.subset.ttf。 */
