{
    (void)a;
    lp_ui_clear();
    if (s_screen == SCR_DIAL && UD.value != NULL) {
        if (UD.unit != NULL) {
            lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
        }
        dial_content(s_mode);
    }
    hint_clear();
}

static void lp_fade_exec(void *var, int32_t v)
{
    (void)var;
    if (LP.arc != NULL) {
        lv_arc_set_value(LP.arc, (int)v);
    }
    if (LP.track != NULL) {
        lv_obj_set_style_arc_opa(LP.track, (lv_opa_t)(255 * v / 100), 0);
    }
}

static void lp_cancel(void)
{
    /* ANIMATION #6：120ms ease-out 进度回到 0。 */
    lv_anim_t a;
    const int start = LP.pct;

    LP.active = false;
    if (lp_uses_hub() && LP.arc != NULL) {
        lv_anim_init(&a);
        lv_anim_set_var(&a, LP.arc);
        lv_anim_set_values(&a, start, 0);
        lv_anim_set_duration(&a, 120);
        lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
        lv_anim_set_exec_cb(&a, lp_fade_exec);
        lv_anim_set_ready_cb(&a, lp_cancel_done);
        lv_anim_start(&a);
    } else {
        lp_cancel_done(NULL);
    }
}

