                const uint32_t held = lv_tick_get() - LP.t0;

                if (held < 160) {
                    LP.active = false;
                    lp_ui_clear();
                    hint_clear();
                    if (s_screen == SCR_DIAL) {
                        dial_content(s_mode);
                    }
                    do_short(key);
