        tri.p[0].x = x2;
        tri.p[0].y = base;
        tri.p[1].x = x1;
        tri.p[1].y = base;
        tri.p[2].x = x1;
        tri.p[2].y = y1;
        lv_draw_triangle(&layer, &tri);

        lv_draw_line_dsc_init(&ld);
